'use strict';
const $=s=>document.querySelector(s),escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Number(n).toLocaleString('ru-RU')+' ₽';
let services=[],category='Все',search='',showAll=false,step=0,b={},savedId=null,readError=false;
const categories=['Все','ПОДОЛОГИЯ','Педикюр и Маникюр ЭСТЕТИКА','Ногтевой Сервис'],categoryLabels=['Все услуги','Подология','Эстетический уход','Ногтевой сервис'];
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow'}).format(new Date()),clock=m=>String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0'),dateText=d=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',weekday:'long'}),service=id=>services.find(s=>s.id===Number(id));
const sum=()=>b.ids.reduce((n,id)=>n+service(id).price,0),duration=()=>b.ids.reduce((n,id)=>n+service(id).duration,0),isFloating=()=>b.ids.some(id=>service(id).floating),direction=()=>b.ids.length?service(b.ids[0]).category:null;
function records(){try{let v=JSON.parse(localStorage.getItem('kut-website-bookings-v1')||'[]');if(!Array.isArray(v))throw Error();return v}catch(e){readError=true;return []}}
function available(date,start,dur,cat){return date>=today()&&start>=600&&start+dur<=1260&&!(date===today()&&new Date(date+'T'+clock(start)+':00+03:00')<=new Date())&&!records().some(r=>r.status!=='cancelled'&&r.date===date&&r.category===cat&&start<r.start+r.duration&&start+dur>r.start)}
function getSlots(){let list=[];for(let m=600;m+duration()<=1260;m+=15)if(available(b.date,m,duration(),direction()))list.push(m);return list}
function selectCategory(c){category=c;search='';showAll=false;$('#search').value='';renderServices();$('#services').scrollIntoView({behavior:'smooth'});document.querySelector('nav').classList.remove('open')}
function renderServices(){let filtered=services.filter(s=>(category==='Все'||s.category===category)&&s.name.toLowerCase().includes(search.toLowerCase())),list=showAll?filtered:filtered.slice(0,8);$('#category-tabs').innerHTML=categories.map((c,i)=>`<button class="${c===category?'active':''}" onclick="selectCategory('${c}')">${categoryLabels[i]}</button>`).join('');$('#result-count').textContent='Найдено: '+filtered.length;const summary=document.querySelector('#services .section-heading p');if(summary)summary.textContent='Выберите услугу. Стоимость и длительность указаны до записи.';$('#service-list').innerHTML=list.map((s,i)=>`<article class="service"><span class="service-num">${String(i+1).padStart(2,'0')}</span><div><h3>${escapeHTML(s.name)}</h3><small>${categoryLabels[categories.indexOf(s.category)]}</small></div><span class="duration">${s.duration} мин</span><span class="price">${s.floating?'от ':''}${money(s.price)}</span><button aria-label="Записаться: ${escapeHTML(s.name)}" onclick="openBooking(${s.id})">↗</button></article>`).join('')||'<p class="empty">Услуга не найдена. Попробуйте другое название.</p>';$('#show-more').hidden=filtered.length<=8;$('#show-more').innerHTML=showAll?'Свернуть список ↑':`Показать все ${filtered.length} услуг ↓`}
function chooseConsultation(){const c=services.find(s=>s.name.trim().toUpperCase()==='КОНСУЛЬТАЦИЯ ПОДОЛОГА'&&s.price===0);if(c)openBooking(c.id)}
$('#search').addEventListener('input',e=>{search=e.target.value;showAll=false;renderServices()});
const CRM_BASE=['localhost','127.0.0.1'].includes(location.hostname)?'http://127.0.0.1:8787':'https://podocare-center-crm.rainyplum10.chatgpt.site';
function openBooking(id){location.assign(CRM_BASE+'/client'+(id?'?service='+encodeURIComponent(id):''))}
function closeBooking(){$('#booking-dialog').close()}
function error(t){$('#booking-error').textContent=t}
function selectedSummary(){return `${b.ids.length} услуг · ${duration()} мин · ${isFloating()?'от ':''}${money(sum())}`}
function renderBooking(){const names=['Услуги','Дата и время','Контакты','Проверка'];let html=`<div class="dialog-top"><h2>${step===4?'Ваш следующий шаг':'Запись на приём'}</h2><button class="close" aria-label="Закрыть запись" onclick="closeBooking()">×</button></div>`;
if(step===4){let r=records().find(r=>r.id===savedId);html+=`<div class="success"><span>✓</span><h3>Тестовая запись подтверждена</h3><p>${dateText(r.date)} · ${clock(r.start)}–${clock(r.start+r.duration)}</p><p>${r.names.map(escapeHTML).join('<br>')}</p><p>${r.floating?'от ':''}${money(r.price)} · ${r.duration} мин</p><div class="notice">Подтверждение автоматическое в рамках теста. Запись существует только в этом браузере. Она не отправлена в центр или в CRM. Для реального визита свяжитесь с центром.</div><button class="primary" onclick="downloadBooking()">Сохранить в календарь ↓</button><p><button class="minor-link" onclick="manageBookings()">Мои тестовые записи · отмена и перенос</button></p><p><a class="text-link" href="https://t.me/podologKUTSYTOY" target="_blank" rel="noopener">Написать центру в Telegram ↗</a></p></div>`;$('#booking-content').innerHTML=html;return}
html+=`<div class="steps">${names.map((n,i)=>`<span class="${i===step?'current':''}">${i+1}. ${n}</span>`).join('')}</div>`;
if(step===0)html+=`<div class="notice">Можно выбрать несколько услуг одного направления. Если сомневаетесь, начните с консультации подолога.</div><input class="booking-search" placeholder="Найти услугу…" aria-label="Поиск услуги для записи" oninput="renderBookingServices(this.value)"><div id="booking-services" class="booking-list"></div>`;
if(step===1)html+=`<div class="notice">Центр работает ежедневно с 10:00 до 21:00, Москва. В этом предпросмотре время демонстрационное: реальные смены специалистов ещё не подключены.</div><p style="font-size:12px">${categoryLabels[categories.indexOf(direction())]} · ${duration()} мин</p><label class="field">Дата посещения<input type="date" min="${today()}" value="${b.date}" onchange="b.date=this.value;b.start=null;renderBooking()"></label><h3 style="font-size:13px">Свободное время</h3><div class="slots">${getSlots().map(m=>`<button class="slot ${b.start===m?'selected':''}" onclick="b.start=${m};renderBooking()">${clock(m)}</button>`).join('')}</div>${!getSlots().length?'<div class="empty">На эту дату нет подходящего времени. Выберите другую дату.</div>':''}`;
if(step===2)html+=`<div class="notice">Это тестовая форма. Используйте вымышленные имя и телефон.</div><label class="field">Ваше имя<input id="client-name" placeholder="Тестовый клиент" maxlength="100" autocomplete="name" value="${escapeHTML(b.name)}" oninput="b.name=this.value"></label><label class="field">Удобный канал связи<select aria-label="Канал связи" onchange="b.channel=this.value;renderBooking()">${channels.map(c=>`<option ${b.channel===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">${contactLabel(b.channel)}<input id="client-contact" maxlength="100" placeholder="${contactPlaceholder(b.channel)}" value="${escapeHTML(b.contact)}" oninput="b.contact=this.value"></label><p class="form-help">Выберите один канал. СМС не отправляем. Автоматическая отправка в мессенджеры пока не подключена.</p><label class="field">Комментарий — по желанию<textarea rows="3" maxlength="1000" placeholder="Комментарий к записи" oninput="b.comment=this.value">${escapeHTML(b.comment)}</textarea></label><label class="checks"><input type="checkbox" ${b.ack?'checked':''} onchange="b.ack=this.checked"> Понимаю, что запись тестовая и не отправляется в центр.</label>`;
if(step===3)html+=`<div class="notice">Всё готово. Проверьте услуги, дату и контакты.</div><h3 style="font-size:20px">${dateText(b.date)}</h3><p>${clock(b.start)}–${clock(b.start+duration())} · Москва</p><p style="font-size:12px">${escapeHTML(b.name)} · ${escapeHTML(b.channel)}: ${escapeHTML(b.contact)}</p>${b.ids.map(id=>{let s=service(id);return `<div class="summary-line"><span>${escapeHTML(s.name)}<small>${s.duration} мин</small></span><b style="white-space:nowrap">${s.floating?'от ':''}${money(s.price)}</b></div>`}).join('')}${b.comment?`<p style="font-size:12px">Комментарий: ${escapeHTML(b.comment)}</p>`:''}<p class="muted" style="font-size:11px">Для услуг с ценой «от» итоговая сумма уточняется на приёме.</p>`;
html+=`<div id="booking-error" class="error" role="alert"></div><div class="booking-bottom"><div>${selectedSummary()}</div><div><button onclick="previousStep()" style="font-size:11px;padding:12px 17px">${step?'Назад':'Закрыть'}</button> <button class="primary" onclick="${step===3?'submitBooking()':'nextStep()'}">${step===3?'Создать тестовую запись':'Продолжить'} ↗</button></div></div>`;
$('#booking-content').innerHTML=html;if(step===0)renderBookingServices('');$('#booking-dialog').scrollTop=0}
function renderBookingServices(q){let list=services.filter(s=>s.name.toLowerCase().includes(q.toLowerCase()));$('#booking-services').innerHTML=list.map(s=>`<button class="pick ${b.ids.includes(s.id)?'selected':''}" onclick="toggleService(${s.id})"><span>${escapeHTML(s.name)}<small>${categoryLabels[categories.indexOf(s.category)]} · ${s.duration} мин</small></span><span class="price">${b.ids.includes(s.id)?'✓ ':''}${s.floating?'от ':''}${money(s.price)}</span></button>`).join('')||'<div class="empty">Нет подходящих услуг</div>'}
function toggleService(id){const existing=b.ids.includes(id);if(!existing&&b.ids.length&&service(id).category!==direction())return error('Эта услуга другого направления. Для неё создайте отдельную запись.');b.ids=existing?b.ids.filter(x=>x!==id):[...b.ids,id];b.start=null;let q=$('.booking-search').value;renderBookingServices(q);$('.booking-bottom>div').textContent=selectedSummary();error('')}
function previousStep(){if(step===0)return closeBooking();step--;renderBooking()}
function nextStep(){if(step===0){if(!b.ids.length)return error('Выберите хотя бы одну услугу.');if(duration()>660)return error('Услуги не помещаются в один рабочий день. Разделите их на несколько визитов.')}if(step===1){if(b.start===null||!available(b.date,b.start,duration(),direction()))return error('Выберите доступное время.')}if(step===2){if(b.name.trim().length<2)return error('Укажите имя, минимум два символа.');if(!validContact(b.channel,b.contact))return error('Проверьте контакт для выбранного канала связи.');if(!b.ack)return error('Подтвердите, что запись тестовая.')}step++;renderBooking()}
function submitBooking(){let list=records();if(readError)return error('Не удалось прочитать сохранённые записи. Новые данные не будут перезаписаны.');if(!available(b.date,b.start,duration(),direction()))return error('Время уже занято или прошло. Вернитесь и выберите другое.');let r={id:crypto.randomUUID(),ids:[...b.ids],names:b.ids.map(id=>service(id).name),category:direction(),date:b.date,start:b.start,duration:duration(),name:b.name.trim(),channel:b.channel,contact:b.contact.trim(),comment:b.comment.trim(),price:sum(),floating:isFloating(),status:'confirmed',created:new Date().toISOString()};list.push(r);try{localStorage.setItem('kut-website-bookings-v1',JSON.stringify(list));savedId=r.id;step=4;renderBooking()}catch(e){error('Браузер не разрешает сохранить данные. Запись не создана.')}}
function calendarEscape(t){return t.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
function calendarText(r){const utc=m=>new Date(r.date+'T'+clock(m)+':00+03:00').toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Kut//Prototype//RU','BEGIN:VEVENT','UID:'+r.id+'@kut-prototype','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART:'+utc(r.start),'DTEND:'+utc(r.start+r.duration),'SUMMARY:'+calendarEscape('ТЕСТ — Куцытой: '+r.names.join(', ')),'DESCRIPTION:Тестовая запись. Не отправлена в центр.','END:VEVENT','END:VCALENDAR'].join('\r\n')}
function downloadBooking(){let r=records().find(r=>r.id===savedId);if(!r)return;const url=URL.createObjectURL(new Blob([calendarText(r)],{type:'text/calendar;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='kut-test-appointment.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#booking-dialog').addEventListener('click',e=>{if(e.target===$('#booking-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeBooking()}});
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>document.querySelector('nav').classList.remove('open')));
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('js-motion');let observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
fetch(CRM_BASE+'/api/catalog').then(r=>{if(!r.ok)throw Error('catalog');return r.json()}).then(data=>{services=data.services.map(s=>({...s,id:Number(s.id)})).sort((a,b)=>{let pa=/первичный прием/i.test(a.name)?-2:/консультация подолога/i.test(a.name)?-1:0,pb=/первичный прием/i.test(b.name)?-2:/консультация подолога/i.test(b.name)?-1:0;return pa-pb||categories.indexOf(a.category)-categories.indexOf(b.category)});renderServices()}).catch(()=>{$('#service-list').innerHTML='<div class="empty">Каталог не загрузился. Обновите страницу или свяжитесь с центром по телефону +7 (985) 059-27-77.</div>'});

const channels=['Telegram','WhatsApp','Viber','MAX','ВКонтакте'];
function contactLabel(c){return ['WhatsApp','Viber'].includes(c)?'Номер телефона в '+c:'Имя пользователя, ссылка или телефон в '+c}
function contactPlaceholder(c){return ['WhatsApp','Viber'].includes(c)?'+7 999 000-00-00':c==='ВКонтакте'?'Ссылка на профиль VK':'@username или номер телефона'}
function validContact(c,v){v=(v||'').trim();if(['WhatsApp','Viber'].includes(c)){const d=v.replace(/\D/g,'');return /^\+?[\d\s()\-]+$/.test(v)&&d.length>=10&&d.length<=15}return v.length>=3&&v.length<=100&&!/[<>]/.test(v)}
function openCertificate(src,title){$('#certificate-image').src=src;$('#certificate-title').textContent=title;$('#certificate-dialog').showModal()}
function closeCertificate(){$('#certificate-dialog').close()}
let products=[],basket={},order={};
function renderProducts(){$('#product-list').innerHTML=products.map((p,i)=>`<article class="product-card"><div class="product-visual" role="img" aria-label="Условная иллюстрация упаковки, фотография появится позже"><div class="bottle">✳</div><small>Иллюстрация · фото добавим позже</small></div><div class="product-info"><div class="eyebrow">ДОМАШНИЙ УХОД / ${String(i+1).padStart(2,'0')}</div><h3>${escapeHTML(p.name)}</h3><p>Бренд, состав и объём упаковки уточняются.<br>Наличие подтвердит администратор.</p><div class="product-price"><b>${money(p.price)}</b><button onclick="openOrder('${escapeHTML(p.id)}')">Заказать ↗</button></div></div></article>`).join('')}
function openOrder(id){location.assign(CRM_BASE+'/client?product='+encodeURIComponent(id));return;basket={[id]:1};order={name:'',channel:'Telegram',contact:'',delivery:'pickup',address:'',comment:'',ack:false};renderOrder();$('#order-dialog').showModal()}
function orderTotal(){return products.reduce((n,p)=>n+p.price*(basket[p.id]||0),0)}
function renderOrder(){let items=products.filter(p=>basket[p.id]);$('#order-content').innerHTML=`<div class="dialog-top"><h2>Заказ домашнего ухода</h2><button class="close" onclick="$('#order-dialog').close()" aria-label="Закрыть заказ">×</button></div><div class="notice">Тестовый заказ: сохраняется только в вашем браузере. Центр не получит заявку. Реальный заказ можно обсудить по телефону или в Telegram.</div>${items.map(p=>`<div class="order-item"><div><b>${escapeHTML(p.name)}</b><small>${money(p.price)} за единицу</small></div><div class="quantity"><button aria-label="Уменьшить количество" onclick="changeQuantity(${p.id},-1)">−</button><span>${basket[p.id]}</span><button aria-label="Увеличить количество" onclick="changeQuantity(${p.id},1)">+</button></div></div>`).join('')}<label class="field">Добавить товар<select onchange="addProduct(this.value)"><option value="">Выберите из каталога</option>${products.map(p=>`<option value="${p.id}">${escapeHTML(p.name)} · ${money(p.price)}</option>`).join('')}</select></label><div class="summary-line"><b>Товары</b><b>${money(orderTotal())}</b></div><div class="order-grid"><label class="field">Ваше имя<input value="${escapeHTML(order.name)}" maxlength="100" placeholder="Тестовый клиент" oninput="order.name=this.value"></label><label class="field">Способ получения<select onchange="order.delivery=this.value;renderOrder()"><option value="pickup" ${order.delivery==='pickup'?'selected':''}>Самовывоз из центра</option><option value="delivery" ${order.delivery==='delivery'?'selected':''}>Доставка по согласованию</option></select></label><label class="field">Канал связи<select onchange="order.channel=this.value;renderOrder()">${channels.map(c=>`<option ${order.channel===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">${contactLabel(order.channel)}<input value="${escapeHTML(order.contact)}" maxlength="100" placeholder="${contactPlaceholder(order.channel)}" oninput="order.contact=this.value"></label></div>${order.delivery==='delivery'?`<label class="field">Адрес доставки<input value="${escapeHTML(order.address)}" maxlength="300" placeholder="Тестовый адрес" oninput="order.address=this.value"></label><p class="form-help">Способ, стоимость и срок доставки согласовываются отдельно. В итог товаров доставка не включена. Оплата при доставке.</p>`:'<p class="form-help">Москва, Петрозаводская, 28 к. 1, первый этаж. Ежедневно 10:00–21:00. Оплата на месте.</p>'}<label class="field">Комментарий<textarea maxlength="1000" rows="2" oninput="order.comment=this.value">${escapeHTML(order.comment)}</textarea></label><label class="checks"><input type="checkbox" ${order.ack?'checked':''} onchange="order.ack=this.checked"> Понимаю, что заказ тестовый. Использую вымышленные данные.</label><p class="form-help">Без онлайн-оплаты и предоплаты. Наличие и характеристики товаров уточняются.</p><div id="order-error" class="error" role="alert"></div><div class="booking-bottom"><b>${money(orderTotal())}</b><button class="primary" onclick="submitOrder()">Создать тестовый заказ ↗</button></div>`}
function changeQuantity(id,n){let q=(basket[id]||0)+n;if(q>99)return;if(q<=0)delete basket[id];else basket[id]=q;renderOrder()}
function addProduct(id){if(!id)return;basket[id]=Math.min(99,(basket[id]||0)+1);renderOrder()}
function submitOrder(){const fail=t=>$('#order-error').textContent=t;if(!Object.keys(basket).length)return fail('Добавьте товар.');if(order.name.trim().length<2)return fail('Укажите имя.');if(!validContact(order.channel,order.contact))return fail('Проверьте контакт для связи.');if(order.delivery==='delivery'&&order.address.trim().length<5)return fail('Укажите адрес доставки.');if(!order.ack)return fail('Подтвердите, что заказ тестовый.');try{let all=JSON.parse(localStorage.getItem('kut-test-orders-v1')||'[]');if(!Array.isArray(all))throw Error();let r={id:crypto.randomUUID(),...order,items:products.filter(p=>basket[p.id]).map(p=>({id:p.id,name:p.name,price:p.price,quantity:basket[p.id]})),total:orderTotal(),status:'test',created:new Date().toISOString()};all.push(r);localStorage.setItem('kut-test-orders-v1',JSON.stringify(all));$('#order-content').innerHTML=`<div class="success"><span>✓</span><h3>Тестовый заказ сохранён</h3><p>${r.items.map(p=>escapeHTML(p.name)+' × '+p.quantity).join('<br>')}</p><p><b>${money(r.total)}</b> · ${r.delivery==='delivery'?'доставка по согласованию':'самовывоз'}</p><div class="notice">Заявка не отправлена в центр. Для настоящего заказа свяжитесь с администратором. Оплата при получении.</div><p><a class="text-link" href="tel:+79850592777">Позвонить +7 (985) 059-27-77 ↗</a></p><p><a class="text-link" href="https://t.me/podologKUTSYTOY" target="_blank" rel="noopener">Написать в Telegram ↗</a></p><button onclick="$('#order-dialog').close()">Закрыть</button></div>`}catch(e){fail('Не удалось сохранить заказ в браузере. Заказ не создан.')}}
function canManage(r){return r.status!=='cancelled'&&new Date(r.date+'T'+clock(r.start)+':00+03:00').getTime()-Date.now()>=3*3600000}
function manageBookings(){location.assign(CRM_BASE+'/client')}
function cancelLocalBooking(id){let list=records(),r=list.find(r=>r.id===id);if(!r||!canManage(r))return manageBookings();r.status='cancelled';try{localStorage.setItem('kut-website-bookings-v1',JSON.stringify(list));manageBookings()}catch(e){alert('Не удалось сохранить изменение.')}}
function showReschedule(id){let r=records().find(r=>r.id===id);if(!r||!canManage(r))return manageBookings();$('#booking-content').innerHTML=`<div class="dialog-top"><h2>Перенос тестовой записи</h2><button class="close" onclick="manageBookings()" aria-label="Назад">×</button></div><p>${r.names.map(escapeHTML).join('<br>')}</p><label class="field">Новая дата<input id="reschedule-date" type="date" min="${today()}" value="${r.date}" onchange="rescheduleSlots('${id}')"></label><label class="field">Свободное время<select id="reschedule-time"></select></label><div id="reschedule-error" class="error" role="alert"></div><button class="primary" onclick="saveReschedule('${id}')">Сохранить перенос</button>`;rescheduleSlots(id)}
function rescheduleAvailable(r,d,m){return d>=today()&&m>=600&&m+r.duration<=1260&&new Date(d+'T'+clock(m)+':00+03:00')>new Date()&&!records().some(a=>a.id!==r.id&&a.status!=='cancelled'&&a.category===r.category&&a.date===d&&m<a.start+a.duration&&m+r.duration>a.start)}
function rescheduleSlots(id){let r=records().find(r=>r.id===id),d=$('#reschedule-date').value,out=[];for(let m=600;m+r.duration<=1260;m+=15)if(rescheduleAvailable(r,d,m))out.push(m);$('#reschedule-time').innerHTML=out.length?out.map(m=>`<option value="${m}">${clock(m)}</option>`).join(''):'<option value="">Нет свободного времени</option>'}
function saveReschedule(id){let all=records(),r=all.find(r=>r.id===id),d=$('#reschedule-date').value,v=$('#reschedule-time').value;if(!r||!canManage(r)||v===''||!rescheduleAvailable(r,d,Number(v)))return $('#reschedule-error').textContent='Перенос недоступен. Проверьте время и правило 3 часов.';r.date=d;r.start=Number(v);try{localStorage.setItem('kut-website-bookings-v1',JSON.stringify(all));manageBookings()}catch(e){$('#reschedule-error').textContent='Изменение не сохранено.'}}
fetch(CRM_BASE+'/api/catalog').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{products=data.products;renderProducts();if(!products.length)$('#product-list').innerHTML='<p class="empty">Наличие товаров уточняется. Позвоните администратору или напишите в Telegram.</p>'}).catch(()=>{$('#product-list').innerHTML='<p class="empty">Каталог товаров недоступен. Уточните наличие по телефону центра.</p>'});

function toggleNavigation(){const nav=document.querySelector('nav');const isOpen=nav.classList.toggle('open');const button=document.querySelector('.menu');button.setAttribute('aria-expanded',String(isOpen));button.setAttribute('aria-label',isOpen?'Закрыть меню':'Открыть меню')}
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('.menu').setAttribute('aria-expanded','false');document.querySelector('.menu').setAttribute('aria-label','Открыть меню')}));
window.addEventListener('resize',()=>{if(window.innerWidth>1100){document.querySelector('nav').classList.remove('open');document.querySelector('.menu').setAttribute('aria-expanded','false')}});
